p(x)p(-x)
&=(x-x_1)(x-x_2)(x-x_3)\times  -(x+x_1)(x+x_2)(x+x_3)\\
&=-(x^2-x_1^2)(x^2-x_2^2)(x^2-x_3^2).
\end{align} 
