-1/\sqrt[]{3} & -1/\sqrt[]{3} & 2/\sqrt[]{3}
\end{bmatrix}
\end{align*}
\begin{align*}
X&=SJ^{1/4}S^{-1} \\
A &= 
\begin{bmatrix}
1 &0 &1 \\
